{
 "app_name": "venmo",
 "api_name": "create_payment_request",
 "path": "/venmo/payment_requests",
 "method": "POST",
 "description": "Send a payment request.",
 "parameters": [
  {
   "name": "user_email",
   "type": "string",
   "required": true,
   "description": "Email address of the receiver user.",
   "default": null,
   "constraints": [
    "value is email address"
   ]
  },
  {
   "name": "amount",
   "type": "number",
   "required": true,
   "description": "Amount of the payment request.",
   "default": null,
   "constraints": [
    "value > 0.0"
   ]
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from venmo app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "description",
   "type": "string",
   "required": false,
   "description": "Description of or note about the payment request.",
   "default": "",
   "constraints": []
  },
  {
   "name": "private",
   "type": "boolean",
   "required": false,
   "description": "The privacy of the transaction on approval of the payment request.",
   "default": false,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string",
   "payment_request_id": 1
  },
  "failure": {
   "message": "string"
  }
 }
}
{
 "app_name": "venmo",
 "api_name": "approve_payment_request",
 "path": "/venmo/payment_requests/{payment_request_id}/approve",
 "method": "POST",
 "description": "Approve a payment request.",
 "parameters": [
  {
   "name": "payment_request_id",
   "type": "integer",
   "required": true,
   "description": "ID of the payment request to approve.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from venmo app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "payment_card_id",
   "type": "integer",
   "required": false,
   "description": "ID of the payment card to use for approving the payment request. If not passed, Venmo balance will be used.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string"
  },
  "failure": {
   "message": "string"
  }
 }
}

